diff --git a/website/layouts/_default/baseof.html b/website/layouts/_default/baseof.html
index 132feec..4a9c9fa 100644
--- a/website/layouts/_default/baseof.html
+++ b/website/layouts/_default/baseof.html
@@ -17,14 +17,19 @@
   {{ if hugo.IsProduction }}
   <link rel="stylesheet" href="{{ "css/consent.css" | relURL }}" media="print" onload="this.media='all'">
   <noscript><link rel="stylesheet" href="{{ "css/consent.css" | relURL }}"></noscript>
-  <script defer src="{{ "js/consent.js" | relURL }}"></script>
+  {{/*
+    Consent Mode v2 requires the default consent state to be set BEFORE
+    any gtag('config', ...) call. consent.js installs that default, so it
+    must run synchronously before the inline GA bootstrap below — do NOT
+    add `defer` here.
+  */}}
+  <script src="{{ "js/consent.js" | relURL }}"></script>
+  <script async src="https://www.googletagmanager.com/gtag/js?id={{ site.Config.Services.GoogleAnalytics.ID }}"></script>
   <script>
     window.dataLayer = window.dataLayer || [];
     function gtag(){dataLayer.push(arguments);}
     gtag('js', new Date());
-    gtag('config', '{{ site.Config.Services.GoogleAnalytics.ID }}', { send_page_view: false });
-    (function(){var s=document.createElement('script');s.src='https://www.googletagmanager.com/gtag/js?id={{ site.Config.Services.GoogleAnalytics.ID }}';s.async=true;
-    if('requestIdleCallback' in window){requestIdleCallback(function(){document.head.appendChild(s)})}else{window.addEventListener('load',function(){document.head.appendChild(s)})}})();
+    gtag('config', '{{ site.Config.Services.GoogleAnalytics.ID }}');
   </script>
   {{ end }}
 </head>
diff --git a/website/static/js/consent.js b/website/static/js/consent.js
index 4bca07e..46384ca 100644
--- a/website/static/js/consent.js
+++ b/website/static/js/consent.js
@@ -44,11 +44,13 @@
   try { stored = localStorage.getItem(STORAGE_KEY); } catch (e) { /* ignore */ }

   if (stored === 'granted') {
+    // GA4 sends page_view automatically when analytics_storage flips to granted,
+    // so we deliberately do NOT call gtag('event', 'page_view') here.
     gtag('consent', 'update', GRANTED);
-    gtag('event', 'page_view');
     return;
   }
   if (stored === 'denied') {
+    // Cookieless pings still flow with denied consent — no further action needed.
     return;
   }

@@ -64,8 +66,8 @@

     acceptBtn.addEventListener('click', function () {
       try { localStorage.setItem(STORAGE_KEY, 'granted'); } catch (e) { /* ignore */ }
+      // page_view is sent automatically by GA4 once analytics_storage is granted.
       gtag('consent', 'update', GRANTED);
-      gtag('event', 'page_view');
       banner.hidden = true;
     });

